using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Text;using System.Security.Cryptography;
public static class WriterBench {
 public static string Run(string root,int rate,int count,int pad,int batch) {
  var sink=new AuthoritativeEvents(root,batch:batch);string raw="{\"kind\":\"start\",\"pid\":100,\"name\":\"SYNTHETIC_ONLY"+new string('x',pad)+"\"}";long t=Stopwatch.GetTimestamp();int done=0;
  for(int i=0;i<count;i++){if(rate>0){long target=t+(long)(i*(double)Stopwatch.Frequency/rate);while(Stopwatch.GetTimestamp()<target)Thread.SpinWait(16);}if(!sink.Publish("CIM_PROCESS_NOTIFICATION","callback",raw,"100"))break;done++;}
  double producer=(Stopwatch.GetTimestamp()-t)/(double)Stopwatch.Frequency;sink.Finish(0,0);double total=(Stopwatch.GetTimestamp()-t)/(double)Stopwatch.Frequency;sink.DiagnosticSave(Path.Combine(root,"timings.json"));string result="{\"targetRate\":"+rate+",\"requested\":"+count+",\"completed\":"+done+",\"producerSeconds\":"+producer.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"totalSeconds\":"+total.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"fault\":"+AuthoritativeEvents.Quote(sink.Failure)+",\"mode\":\"actual writer / synthetic records / no live observers\"}";WriterTiming.SaveNew(Path.Combine(root,"result.json"),result);return result;
 }
 public static string Raw(string root) {byte[] b=new byte[65536];long size=128*1024*1024;var w=Stopwatch.StartNew();using(var f=new FileStream(Path.Combine(root,"raw.bin"),FileMode.CreateNew,FileAccess.Write,FileShare.Read,65536,FileOptions.SequentialScan)){for(long i=0;i<size;i+=b.Length)f.Write(b,0,b.Length);double write=w.Elapsed.TotalSeconds;long q=Stopwatch.GetTimestamp();f.Flush(true);double flush=(Stopwatch.GetTimestamp()-q)/(double)Stopwatch.Frequency;string s="{\"bytes\":"+size+",\"writeSeconds\":"+write.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+",\"flushSeconds\":"+flush.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"}";WriterTiming.SaveNew(Path.Combine(root,"raw-result.json"),s);return s;}}
}
